var numbers = new List<int> { 1, 2, 3, 4, 5, 6 };

var evenSquares = numbers
    .Where(n => n % 2 == 0)
    .Select(n => n * n);

foreach (var n in evenSquares)
    Console.WriteLine(n);   // 4, 16, 36

